function byPath(rs){const m={};for(const r of rs){const k=r.path;m[k]=m[k]||{n:0,e:0};m[k].n++;if(r.status>=500)m[k].e++;}return m;}
const cs=byPath(canary), ss=byPath(stable);
print('path | canary n/5xx | stable n/5xx');
for(const p of Object.keys(ss)){print(p+' | '+cs[p].n+'/'+cs[p].e+' | '+ss[p].n+'/'+ss[p].e);}
print('TOTAL canary 5xx='+canary.filter(r=>r.status>=500).length+' stable 5xx='+stable.filter(r=>r.status>=500).length);
print('canary 5xx timestamps: '+canary.filter(r=>r.status>=500).map(r=>Math.round(r.t)).join(','));
print('canary 5xx statuses: '+canary.filter(r=>r.status>=500).map(r=>r.status).join(','));
print('canary 5xx latencies: '+canary.filter(r=>r.status>=500).map(r=>Math.round(r.ms)).join(','));
const co=canary.filter(r=>r.path==='/checkout'), so=stable.filter(r=>r.path==='/checkout');
print('checkout p50/p95/p99 canary: '+pct(co.map(r=>r.ms),50)+'/'+pct(co.map(r=>r.ms),95)+'/'+pct(co.map(r=>r.ms),99));
print('checkout p50/p95/p99 stable: '+pct(so.map(r=>r.ms),50)+'/'+pct(so.map(r=>r.ms),95)+'/'+pct(so.map(r=>r.ms),99));
print('canary checkout err% = '+(100*co.filter(r=>r.status>=500).length/co.length).toFixed(2));

const e=canary.filter(r=>r.status>=500);
print('Q1: canary 5xx total='+e.length+' paths='+[...new Set(e.map(r=>r.path))].join(',')+' statuses='+[...new Set(e.map(r=>r.status))].join(',')+' stable 5xx total='+stable.filter(r=>r.status>=500).length+'/'+stable.length);
const cc=canary.filter(r=>r.path==='/checkout'), sc=stable.filter(r=>r.path==='/checkout');
const ce=cc.filter(r=>r.status>=500).length, se=sc.filter(r=>r.status>=500).length;
print('Q2: canary /checkout '+ce+'/'+cc.length+'='+(100*ce/cc.length).toFixed(2)+'% stable /checkout '+se+'/'+sc.length+'='+(100*se/sc.length).toFixed(2)+'%');
const w=[0,0,0,0]; for(const r of e) w[Math.min(3,Math.floor(r.t/30))]++;
print('Q3: canary 5xx window='+w.join(','));
function q(a,n){const s=a.slice().sort((x,y)=>x-y);return s[Math.min(s.length-1,Math.floor(n/100*s.length))];}
const cl=canary.map(r=>r.ms), sl=stable.map(r=>r.ms);
const a=q(cl,95), b=q(sl,95);
print('Q4: p95 canary='+a+' stable='+b+' within5ms='+(Math.abs(a-b)<=5));

